"""Original educational corpus with explicit genres, teaching tags and evidence anchors."""
import re,hashlib
from content_v06 import PACKS,material
THEMES=('campus','travel','life','work','culture','science')
GENRES={'story':'叙事','dialogue':'对话','email':'邮件','notice':'通知','article':'短文','report':'观察报告'}
def rotated_question(id,index,prompt,options,answer,evidence):
 offset=hashlib.sha256((id+str(index)).encode()).digest()[0]%4
 return {'prompt':prompt,'options':options[offset:]+options[:offset],'answer':(answer-offset)%4,'evidence':evidence}
def entry(id,title,level,theme,genre,body,questions,speaking,writing,words,tags,grammar):
 sentences=re.split(r'(?<=[.!?])\s+',body)
 for q in questions:
  if q[3]>=len(sentences):raise ValueError(id+' evidence index '+str(q[3])+' >= '+str(len(sentences)))
 return {'id':id,'title':title,'level':level,'theme':theme,'genre':genre,'body':body,
 'questions':[rotated_question(id,j,p,o,a,sentences[i]) for j,(p,o,a,i) in enumerate(questions)],
 'dictation_index':1,'speaking':speaking,'writing':writing,
 'vocabulary':[{'term':t,'meaning':m,'example':e} for t,m,e in words],
 'tags':tags,'grammar':grammar,'source':'Flow 原创教学示例'}
